import type { NextConfig } from "next";
import os from "node:os";
import { DEFAULT_SETTINGS_TAB } from "./lib/settings-tabs";

const isDev = process.env.NODE_ENV !== "production";

// @smokingmouse/agent + @smokingmouse/llm are normal registry dependencies
// now (real directories inside node_modules) — no symlink games in the
// default install path. This wider `root` only still matters for the local
// SDK-hacking flow (`make link-sdk`, which symlinks the two packages back to
// ~/sdk): Turbopack only follows symlinks *within* its configured root, and
// ~/sdk sits outside the project dir, so root must be a common ancestor.
// Harmless otherwise (long since proven in prod on this machine), so it
// stays unconditional rather than link-detection-conditional.
const projectRoot = os.homedir();

// Allow tunneled dev (e.g. Cloudflare Tunnel, ngrok) to reach next dev.
// Set TRELLIS_DEV_ORIGIN=your.host.example to whitelist a custom origin.
const devOrigin = process.env.TRELLIS_DEV_ORIGIN;

const nextConfig: NextConfig = {
  ...(devOrigin ? { allowedDevOrigins: [devOrigin] } : {}),
  turbopack: {
    root: projectRoot,
  },
  // Codex SDK uses createRequire(import.meta.url) at runtime to resolve the
  // platform-specific CLI binary. Bundling breaks that resolution. Keep it
  // external so it runs from real node_modules.
  // @smokingmouse/agent 是 server-only Node 包(spawn child_process),external 它从 node_modules
  // 直接运行(dist 编译产物),不进 bundler。@smokingmouse/llm 同理(读 fs)。
  serverExternalPackages: ["@openai/codex-sdk", "@openai/codex", "@smokingmouse/agent", "@smokingmouse/llm"],
  // S89: 管理台改成 tab 壳之后的两条路由兼容。放在 next.config 而不是留一张 redirect 页 ——
  // 这里在文件系统路由之前生效，不用为了转发而渲染一个 React 树，也就不会有「先闪一下空页
  // 再跳走」。
  //
  // permanent: false（307）是有意的：308 会被浏览器**永久**缓存，而这两条都还可能再动
  // （/settings 将来若做成有内容的总览页，308 会让老浏览器再也进不去）。本机应用，
  // 少一次 301 缓存的收益远小于把自己锁死的风险。
  async redirects() {
    return [
      // /settings 落到第一个 tab。默认值取自 lib/settings-tabs.ts，改 tab 顺序即改这里。
      {
        source: "/settings",
        destination: `/settings/${DEFAULT_SETTINGS_TAB}`,
        permanent: false,
      },
      // S88 时任务是顶级页 /tasks。书签、Header 旧图标、以及任何贴出去的链接都还指着它。
      { source: "/tasks", destination: "/settings/tasks", permanent: false },
    ];
  },
  // Tunneled dev (Cloudflare CDN, etc.): some CDNs rewrite Next dev's
  // `Cache-Control: no-cache` into `max-age=14400`, so edits to globals.css
  // don't reach the browser for hours. `no-store` is one of the few
  // directives CDNs typically won't override — they treat it as
  // bypass-cache. Only apply in dev; production builds use hashed
  // filenames so caching is actually useful there.
  ...(isDev
    ? {
        async headers() {
          return [
            {
              source: "/_next/:path*",
              headers: [
                {
                  key: "Cache-Control",
                  value:
                    "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0",
                },
              ],
            },
            {
              source: "/",
              headers: [
                {
                  key: "Cache-Control",
                  value: "no-store, no-cache, must-revalidate, max-age=0",
                },
              ],
            },
          ];
        },
      }
    : {}),
};

export default nextConfig;

import type { Metadata, Viewport } from "next";
import "./globals.css";
import { PREF_KEYS } from "@/lib/prefs";

export const metadata: Metadata = {
  title: "Trellis",
  description: "图状的 AI 对话",
  manifest: "/manifest.json",
  appleWebApp: {
    capable: true,
    statusBarStyle: "default",
    title: "Trellis",
  },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  maximumScale: 1,
  // Browser pinch-zoom is disabled so React Flow can own the gesture.
  // The canvas zoom replaces accessibility zoom for this app.
  userScalable: false,
};

// Pre-hydration theme application. Runs before React touches the DOM so
// users never see a flash of the wrong theme (FOUC). Same resolution logic as
// hooks/useTheme.ts. `trellis-theme` stores light/dark/system (legacy two-value
// entries stay valid; missing = system). `trellis-palette` stores the skin id;
// 'default' carries no data-theme attribute.
//
// S89: key 名从 lib/prefs.ts **插值进来**，不再手写字面量。此前这里和 useTheme.ts
// 各硬编码一份，注释写着「keep them in sync if you change either」—— 那种靠人记得
// 同步的约定迟早失效，现在物理上不可能不同步。
const themeScript = `
(function() {
  try {
    var m = localStorage.getItem('${PREF_KEYS.theme}');
    var dark = m === 'dark' || (m !== 'light' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (dark) document.documentElement.classList.add('dark');
    var p = localStorage.getItem('${PREF_KEYS.palette}');
    if (p && p !== 'default') document.documentElement.setAttribute('data-theme', p);
  } catch (_) {}
})();
`;

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="zh-CN" className="h-full antialiased" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeScript }} />
      </head>
      <body className="min-h-full">{children}</body>
    </html>
  );
}

"use client";
import { useEffect, useRef } from "react";
import { useSessionStore } from "@/stores/sessionStore";
import { QuestionInput } from "@/components/QuestionInput";
import { Canvas } from "@/components/Canvas";
import { Header } from "@/components/Header";
import { SessionTabs } from "@/components/SessionTabs";
import { SessionSidebar } from "@/components/SessionSidebar";
import { LinearThreadView } from "@/components/LinearThreadView";
import { NewQuestionPicker } from "@/components/NewQuestionPicker";
import { Outline } from "@/components/Outline";
import { DoneToast } from "@/components/DoneToast";
import { TaskToast } from "@/components/TaskToast";
import { AbortToast } from "@/components/AbortToast";
import { StreamAlertToast } from "@/components/StreamAlertToast";
import { NotesDrawer } from "@/components/NotesDrawer";
import { TerminalPanel } from "@/components/TerminalPanel";
import { WorkspaceFilesDrawer } from "@/components/WorkspaceFilesDrawer";
import { SearchModal } from "@/components/SearchModal";
import { FilePreview } from "@/components/FilePreview";
import { KeyboardHelp } from "@/components/KeyboardHelp";
import { useIsMobile } from "@/hooks/useIsMobile";
import { useEscapeAbort } from "@/hooks/useEscapeAbort";
import { useUnreadNavigation } from "@/hooks/useUnreadNavigation";
import { useNodeKeyboardNav } from "@/hooks/useNodeKeyboardNav";
import { useReconnectStreams } from "@/hooks/useReconnectStreams";
import { useRunPolling } from "@/hooks/useRunPolling";
import { useCliSyncEvents } from "@/hooks/useCliSyncEvents";

export default function Home() {
  const hydrate = useSessionStore((s) => s.hydrate);
  const hydrated = useSessionStore((s) => s.hydrated);
  const session = useSessionStore((s) => s.session);
  const hydrateError = useSessionStore((s) => s.hydrateError);
  const viewMode = useSessionStore((s) => s.viewMode);
  const setViewMode = useSessionStore((s) => s.setViewMode);
  // Remote 新话题 triggers (Header B3 prompt, /clear from any composer) —
  // consumed here instead of inside AddNodeFAB so the picker opens in the
  // linear view too, where the canvas FAB is unmounted.
  const composeRootOpen = useSessionStore((s) => s.composeRootOpen);
  const setComposeRootOpen = useSessionStore((s) => s.setComposeRootOpen);
  const isMobile = useIsMobile();
  useEscapeAbort();
  useUnreadNavigation();
  useNodeKeyboardNav();
  useReconnectStreams();
  useCliSyncEvents();
  // Wave 4: one app-level /api/runs poll feeds running + unread badges to
  // both the tab strip and the sidebar (no per-component intervals).
  useRunPolling();

  useEffect(() => {
    hydrate();
  }, [hydrate]);

  // S88 深链：/?session=<sid>&node=<nid>。任务页的运行历史点进来就走这条 ——
  // 任务层因此一行渲染代码都不用写，用户看到的和自己手动提问完全一样。
  // hydrate 之后再切，否则 loadSession 会被 hydrate 的结果覆盖掉。
  // 用 location 而不是 useSearchParams：后者会逼出 Suspense 边界要求（build 时
  // 才炸），而深链本就是纯客户端行为，没有 SSR 语义可言。
  const loadSession = useSessionStore((s) => s.loadSession);
  const setActiveNode = useSessionStore((s) => s.setActiveNode);
  const deepLinkedRef = useRef<string | null>(null);
  useEffect(() => {
    if (!hydrated || typeof window === "undefined") return;
    const q = new URLSearchParams(window.location.search);
    const deepSession = q.get("session");
    const deepNode = q.get("node");
    if (!deepSession) return;
    // 只跳一次 —— 用户在页面里点别的会话之后不该被 URL 拽回来。
    if (deepLinkedRef.current === deepSession) return;
    deepLinkedRef.current = deepSession;
    void loadSession(deepSession).then(() => {
      if (deepNode) setActiveNode(deepNode);
    });
  }, [hydrated, loadSession, setActiveNode]);

  // 注：--trellis-sb 由 SessionSidebar 发布（宽度可拖拽后归它所有，
  // 这里再按常量发一份就会打架）。

  // #7: mobile lands on the linear thread (the standard phone chat flow) for
  // every mode whenever the user arrives on a (different) session. They can
  // still switch to the canvas; we don't force them back.
  const sessionId = session?.id;
  useEffect(() => {
    if (isMobile && sessionId) setViewMode("linear");
  }, [isMobile, sessionId, setViewMode]);

  if (!hydrated || isMobile === null) {
    return (
      <div className="min-h-screen flex items-center justify-center text-ink-faint text-sm">
        加载中…
      </div>
    );
  }

  return (
    <>
      <Header />
      <SessionSidebar />
      <SessionTabs />
      {hydrateError && (
        <div className="fixed top-12 md:top-[5.25rem] inset-x-0 z-40 bg-warn-muted border-b border-warn-line px-4 py-2 text-xs text-warn-ink">
          ⚠️ 本地存储不可用：{hydrateError}。可以继续问答，但刷新会丢失历史。
        </div>
      )}
      {!session && <QuestionInput />}
      {session && viewMode === "linear" && <LinearThreadView />}
      {session && viewMode === "canvas" && (
        <>
          <Canvas
            onNodeFocus={isMobile ? () => setViewMode("linear") : undefined}
          />
          <button
            type="button"
            onClick={() => setViewMode("linear")}
            className="fixed top-[60px] md:top-[108px] right-3 z-30 px-3 py-2 rounded-full bg-surface border border-line shadow-raise text-xs font-medium text-ink hover:bg-surface-muted active:scale-95 transition-transform"
            title="切换到线性 thread"
          >
            线性
          </button>
        </>
      )}
      {/* B1: mobile outline drawer — mounted top-level so it survives the
          linear view (where Canvas + its rail Outline unmount). Desktop hides
          it (md:hidden) since the rail Outline inside Canvas covers desktop. */}
      {session && <Outline variant="drawer" />}
      {session && composeRootOpen && (
        <NewQuestionPicker onClose={() => setComposeRootOpen(false)} />
      )}
      <DoneToast />
      {/* S88：任务执行完成 / 失败的站内提醒（自带 SSE 订阅）。 */}
      <TaskToast />
      <AbortToast />
      <StreamAlertToast />
      {/* S1 P1：工作区终端。自己判断有没有 workspace（chat 会话直接返回 null），
          所以不在这里加条件 —— 它还要负责在没打开时渲染右下角那个「▲ 终端」把手。 */}
      {session && <TerminalPanel />}
      <NotesDrawer />
      <WorkspaceFilesDrawer />
      <SearchModal />
      <FilePreview />
      <KeyboardHelp />
    </>
  );
}

