2	import { useEffect, useState } from "react";
3	
4	export type SelectionInfo = {
5	  text: string;
6	  rect: DOMRect;
7	  nodeId: string;
8	  // Snapshot of the selected Range, so the popover can paint its own
9	  // highlight (CSS Custom Highlight API) that survives the native selection
10	  // collapsing when the textarea is clicked. Cloned so later selectionchange
11	  // events don't mutate it. May be undefined in browsers without Range.
12	  range?: Range;
13	};
14	
15	// Watches the document for text selections inside elements marked with
16	// data-chat-node-id. Returns the selection info, or null when nothing is
17	// selected (or selection is outside any chat node).
18	export function useSelectionWithin(): SelectionInfo | null {
19	  const [info, setInfo] = useState<SelectionInfo | null>(null);
20	
21	  useEffect(() => {
22	    let timer: number | undefined;
23	    const compute = () => {
24	      const sel = window.getSelection();
25	      if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
26	        setInfo(null);
27	        return;
28	      }
29	      const text = sel.toString().trim();
30	      if (!text) {
31	        setInfo(null);
32	        return;
