        pixelRatio: 2,
        backgroundColor: isDark ? "#1c1917" : "#ffffff",
        cacheBust: true,
      });
      if (!blob) throw new Error("render produced no image");

      // Prefer the clipboard; fall back to a download if it's unavailable
      // or rejected (permissions / unsupported ClipboardItem image type).
      const canClipImage =
        typeof ClipboardItem !== "undefined" &&
        !!navigator.clipboard?.write;
      if (canClipImage) {
        try {
          await navigator.clipboard.write([
            new ClipboardItem({ "image/png": blob }),
          ]);
          setPhase("copied");
        } catch {
          downloadBlob(blob, title);
          setPhase("downloaded");
        }
      } else {
        downloadBlob(blob, title);
        setPhase("downloaded");
      }
      window.setTimeout(() => setPhase("idle"), 2000);
    } catch (err) {
      console.error("[trellis] card image failed:", err);
      setPhase("error");
      window.setTimeout(() => setPhase("idle"), 2500);
    } finally {
      if (wrapper) wrapper.setAttribute("style", prevStyle);
    }
  };

  const label =
    phase === "rendering"
      ? "生成中…"
      : phase === "copied"
        ? "✓ 已复制图片"
        : phase === "downloaded"
          ? "✓ 已下载"
          : phase === "error"
            ? "✗ 失败"
            : "🖼 卡片图";

  return (
    <>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          void run();
        }}
        disabled={phase === "rendering"}
        title="把这条问答渲染成一张卡片图片并复制到剪贴板"
        className="nodrag px-2.5 py-1 rounded border border-line text-ui text-ink-muted hover:bg-surface-muted hover:text-ink-strong transition-colors disabled:opacity-50"
      >
        {label}
      </button>

      {/* Off-screen card laid out (not display:none, which can't be
          rasterized) for html-to-image to capture. Mirrors the app's markdown
          styling so the image matches what the user reads. The wrapper is
          temporarily repositioned on-screen during render — see run(). */}
      <div
        aria-hidden
        style={{ position: "fixed", left: -99999, top: 0, pointerEvents: "none" }}
      >
        <div
          ref={cardRef}
          className="w-[680px] bg-surface px-8 py-7"
        >
          <div className="flex items-start gap-3 mb-5">
            <span className="mt-1 w-1 self-stretch rounded-full bg-accent shrink-0" />
            <h3 className="text-title leading-snug font-semibold text-ink-strong">
              {title}
            </h3>
          </div>
          <div className="md-body text-ink">
            <ReactMarkdown
              remarkPlugins={REMARK_PLUGINS}
              rehypePlugins={REHYPE_FULL}
              components={MD_COMPONENTS}
              urlTransform={MD_URL_TRANSFORM}
            >
              {content}
            </ReactMarkdown>
          </div>
          <div className="mt-6 pt-3 border-t border-line/70 text-label text-ink-faint">
            Trellis · 思维树
